  let body=rows.slice(start,start+size).map(r=>'<tr><td><details><summary>'+esc(r.name)+'</summary><p>'+esc(r.name_zh)+'<br>'+esc(r.category)+'<br>'+esc(r.address)+'<br>'+esc(r.source+' · '+r.native_id)+'<br>Coordinate: '+esc(r.point.variant)+'; covering footprints: '+r.point.covering_footprints+'</p><p>'+r.attachments.map(a=>esc(a.building_id+' · '+a.basis+' · '+(a.first_band===null?'not reached through 60 min':a.first_band+' min band')+(a.qualifies_in_selected_band?' · qualifies':''))).join('<br>')+'</p><button type="button" data-named-point="'+esc(r.record_key)+'">Locate on atlas</button></details></td><td>'+r.first_band+' min</td><td>'+(r.selected_basis==='initial'?'Initial':'Nearest proxy')+(r.rail_added_at_selected_band?' · rail adds':'')+'</td></tr>').join('');
