  await preparePathMap();if(current!==ticket)return;
  let h=await request('/health');if(current!==ticket)return;if(h.version!=='MOBILITY_NETWORK_MAP_V0_7'||h.lookup_sha256!=='3714ecc75cb72df365711d572e3a1b6db6acd2455ba93d1383c2467e1ae29894')throw Error('Local service version differs');if(h.phase!=='ready')throw Error(h.error||'Local service is still loading');
