   if(v.state==='ready'){profile=v.profile;if(profile.grain!==t.grain||profile.id!==t.id||basis&&profile.basis!==basis)throw Error('Native place/basis differs');owner=null;await draw();return}
   if(['error','expired','superseded'].includes(v.state))throw Error(v.message||'Place calculation '+v.state);
   await new Promise(resolve=>root.setTimeout(resolve,500));if(current!==ticket||!active())return
