function setOpacity(v){opacity=Math.max(0,Math.min(1,Number(v)/100));root.document?.querySelectorAll('[data-unet-opacity]').forEach(n=>{n.value=String(Math.round(opacity*100))});root.document?.querySelectorAll('[data-unet-opacity-label]').forEach(n=>{n.textContent=Math.round(opacity*100)+'%'});if(map?.getLayer(layer))map.setPaintProperty(layer,'line-opacity',opacity)}
